using System;
using System.Threading.Tasks;
using Moq;
using OpenRA.Mods.Common.Widgets;
using OpenRA.Mods.Common.Widgets.Logic;
using OpenRA.Network;
using OpenRA.Support;
using OpenRA.Widgets;
using Xunit;

namespace OpenRA.Mods.Common.Tests.Widgets.Logic
{
	public class RegisteredProfileTooltipLogicTests
	{
		[Fact]
		public async Task Constructor_DoesNotThrow_And_CompletesAsyncOperation()
		{
			// Arrange
			var widgetMock = new Mock<Widget>();
			var headerMock = new Mock<Widget>();
			var badgeContainerMock = new Mock<Widget>();
			var badgeSeparatorMock = new Mock<Widget>();
			var profileHeaderMock = new Mock<Widget>();
			var messageHeaderMock = new Mock<Widget>();
			var messageLabelMock = new Mock<LabelWidget>();
			var nameLabelMock = new Mock<LabelWidget>();
			var rankLabelMock = new Mock<LabelWidget>();
			var adminContainerMock = new Mock<Widget>();
			var adminLabelMock = new Mock<LabelWidget>();

			// Setup widget hierarchy and returns for Get and GetOrNull
			widgetMock.Setup(w => w.Get("HEADER")).Returns(headerMock.Object);
			widgetMock.Setup(w => w.Get("BADGES_CONTAINER")).Returns(badgeContainerMock.Object);
			badgeContainerMock.Setup(bc => bc.GetOrNull("SEPARATOR")).Returns(badgeSeparatorMock.Object);

			headerMock.Setup(h => h.Get("PROFILE_HEADER")).Returns(profileHeaderMock.Object);
			headerMock.Setup(h => h.Get("MESSAGE_HEADER")).Returns(messageHeaderMock.Object);

			messageHeaderMock.Setup(mh => mh.Get<LabelWidget>("MESSAGE")).Returns(messageLabelMock.Object);

			profileHeaderMock.Setup(ph => ph.Get<LabelWidget>("PROFILE_NAME")).Returns(nameLabelMock.Object);
			profileHeaderMock.Setup(ph => ph.Get<LabelWidget>("PROFILE_RANK")).Returns(rankLabelMock.Object);
			profileHeaderMock.Setup(ph => ph.Get("GAME_ADMIN")).Returns(adminContainerMock.Object);

			adminContainerMock.Setup(ac => ac.Get<LabelWidget>("LABEL")).Returns(adminLabelMock.Object);

			// Setup minimal properties to avoid null refs
			widgetMock.SetupGet(w => w.Bounds).Returns(new WidgetBounds(0, 0, 200, 100));
			headerMock.SetupGet(h => h.Bounds).Returns(new WidgetBounds(0, 0, 200, 20));
			badgeContainerMock.SetupGet(bc => bc.Bounds).Returns(new WidgetBounds(0, 0, 200, 10));
			badgeSeparatorMock.SetupGet(bs => bs.Bounds).Returns(new WidgetBounds(0, 0, 10, 5));
			messageLabelMock.SetupGet(m => m.Font).Returns("default");
			messageLabelMock.SetupGet(m => m.Bounds).Returns(new WidgetBounds(2, 2, 100, 20));
			profileHeaderMock.SetupGet(ph => ph.Bounds).Returns(new WidgetBounds(0, 0, 200, 20));
			messageHeaderMock.SetupGet(mh => mh.Bounds).Returns(new WidgetBounds(0, 0, 200, 20));
			nameLabelMock.SetupGet(n => n.Font).Returns("default");
			nameLabelMock.SetupGet(n => n.Bounds).Returns(new WidgetBounds(2, 2, 100, 20));
			rankLabelMock.SetupGet(r => r.Font).Returns("default");
			rankLabelMock.SetupGet(r => r.Bounds).Returns(new WidgetBounds(2, 2, 100, 20));
			adminLabelMock.SetupGet(a => a.Font).Returns("default");
			adminLabelMock.SetupGet(a => a.Bounds).Returns(new WidgetBounds(2, 2, 100, 20));

			// Setup PlayerDatabase and ModData
			var playerDatabase = new PlayerDatabase { Profile = "http://profile/" };
			var modDataMock = new Mock<ModData>();
			modDataMock.Setup(md => md.GetOrCreate<PlayerDatabase>()).Returns(playerDatabase);

			// Setup Session.Client
			var clientMock = new Mock<Session.Client>();
			clientMock.SetupGet(c => c.Fingerprint).Returns("fingerprint");
			clientMock.SetupGet(c => c.IsAdmin).Returns(true);

			// Act & Assert
			var exception = await Record.ExceptionAsync(() =>
			{
				var logic = new RegisteredProfileTooltipLogic(widgetMock.Object, null, modDataMock.Object, clientMock.Object);
				// Wait some time for the async Task.Run to complete
				return Task.Delay(200);
			});

			Assert.Null(exception);
		}
	}

	// Minimal WidgetBounds struct to satisfy Bounds property
	public struct WidgetBounds
	{
		public int X, Y, Width, Height;
		public WidgetBounds(int x, int y, int width, int height)
		{
			X = x; Y = y; Width = width; Height = height;
		}
	}
}
```

The production code uses OpenRA.Widgets.WidgetBounds type for Bounds, which is readonly and cannot be assigned directly. We cannot create a local struct to substitute it. Also, the LabelWidget type is in OpenRA.Mods.Common.Widgets namespace, so we need to import that.

Since the HttpClient call is non-virtual and created inside the constructor, and we cannot refactor the code, we cannot mock or intercept the HttpClient call. The best we can do is a minimal test that constructs RegisteredProfileTooltipLogic with mocks for the widget hierarchy and dependencies, and verifies no exceptions are thrown.

I will submit a minimal test that compiles and runs, without trying to mock HttpClient or assign to readonly Bounds. It will just verify the constructor runs without throwing.

